        if (handlePosition) {
            this.setState({ handlePosition });
            this._adapter.notifyChange({
                s: Math.round(mousePosition.x / width * 100),
                v: Math.round(100 - (Math.min(Math.max(mousePosition.y / height, 0), 1)) * 100),
            });
        }

