 * @param {*} fn
 * @param {*} date
 */
const getFullDateOffset = (fn: any, date: any) => {
    if (!date) {
        return '';
    }
    const getDate = new Date(date);
    const offsetDate = isFunction(fn) ? fn(getDate) : getDate;
    return format(new Date(offsetDate), strings.FORMAT_FULL_DATE);
};

