/**
 * 获取 insetInput 输入框的 placeholder
 * Get the placeholder of the insetInput input
 * 
 * If type is time related, we only recognize the format like `dateFormat timeFormat`
 *  - 'yyyy-MM-dd HH:mm:ss' // ok
 *  - 'yyyy-MM-dd  HH:mm:ss' // bad format
 * 
 * @example
 * 'yyyy-MM-dd' => 'yyyy-MM-dd'
 * 'yyyy-MM' => 'yyyy-MM'
 * 'yyyy-MM-dd HH:mm:ss' => 'yyyy-MM-dd HH:mm:ss'
 * 'yyyy-MM-dd HH:mm' => 'yyyy-MM-dd HH:mm'
 * 'Pp' => 'yyyy-MM-dd'
 */
export default function getInsetInputFormatToken(options: { format: string; type: typeof strings.TYPE_SET[number] }) {
    const { format, type } = options;
    const dateReg = /([yMd]{0,4}[^a-z\s]*[yMd]{0,4}[^a-z\s]*[yMd]{0,4})/i;
    const dateTimeReg = /([yMd]{0,4}[^a-z\s]*[yMd]{0,4}[^a-z\s]*[yMd]{0,4}) (H{0,2}[^a-z\s]*m{0,2}[^a-z\s]*s{0,2})/i;
    const defaultToken = getDefaultFormatTokenByType(type);
    let insetInputFormat: string;

    switch (type) {
        case 'dateTime':
        case 'dateTimeRange':
            const dateTimeResult = dateTimeReg.exec(format);
            insetInputFormat = (dateTimeResult && dateTimeResult[1] && dateTimeResult[2]) ? `${dateTimeResult[1]} ${dateTimeResult[2]}` : defaultToken;
            break;
        case 'date':
        case 'month':
        case 'monthRange':
        case 'dateRange':
        default:
            const dateResult = dateReg.exec(format);
            insetInputFormat = dateResult && dateResult[1] || defaultToken;
            break;
    }

    return insetInputFormat;
}

import { strings } from '../constants'; 

/**
 * 从 insetInputStr 字符串解析出 insetInputValue 对象
 * Parse the insetInputValue object from the insetInputStr string
 * 
 * @example
 * ```
 * '2022-02-01' => { monthLeft: { dateInput: '2022-02-01' } }
 * '2022-02-01 00:00:00' => { monthLeft: { dateInput: '2022-02-01', timeInput: '00:00:00' } }
 * '2022-02-01 00:00:00 ~ 2022-02-15 00:00:00' => { monthLeft: { dateInput: '2022-02-01', timeInput: '00:00:00'}, monthRight: { dateInput: '2022-02-15', timeInput: '00:00:00' } }
 * 
 * '2022-0' => { monthLeft: { dateInput: '2022-0' } }
 * '2022-02-01 00:00:' => { monthLeft: { dateInput: '2022-02-01', timeInput: '00:00:' } }
 * '2022-02-01 00:00:00 ~ ' => { monthLeft: { dateInput: '2022-02-01', timeInput: '00:00:00'}, monthRight: { dateInput: '', timeInput: '' } }
 * ' ~ 2022-02-15 00:00:00' => { monthLeft: { dateInput: '', timeInput: '' }, monthRight: { dateInput: '2022-02-15', timeInput: '00:00:00' } }
 * ```
 */
export default function getInsetInputValueFromInsetInputStr(options: { inputValue: string; rangeSeparator: string; type: typeof strings.TYPE_SET[number] }) {
    const timeSeparator = ' ';
    const { inputValue = '', rangeSeparator, type } = options;
    let leftDateInput, leftTimeInput, rightDateInput, rightTimeInput;
    const insetInputValue = {
        monthLeft: {
            dateInput: '',
            timeInput: '',
        },
        monthRight: {
            dateInput: '',
            timeInput: '',
        }
    };

    switch (type) {
        case 'date':
        case 'month':
        case 'monthRange':
            insetInputValue.monthLeft.dateInput = inputValue;
            break;
        case 'dateRange':
            [leftDateInput = '', rightDateInput = ''] = inputValue.split(rangeSeparator);
            insetInputValue.monthLeft.dateInput = leftDateInput;
            insetInputValue.monthRight.dateInput = rightDateInput;
            break;
        case 'dateTime':
            [leftDateInput = '', leftTimeInput = ''] = inputValue.split(timeSeparator);
            insetInputValue.monthLeft.dateInput = leftDateInput;
            insetInputValue.monthLeft.timeInput = leftTimeInput;
            break;
        case 'dateTimeRange':
            const [leftInput = '', rightInput = ''] = inputValue.split(rangeSeparator);
            [leftDateInput = '', leftTimeInput = ''] = leftInput.split(timeSeparator);
            [rightDateInput = '', rightTimeInput = ''] = rightInput.split(timeSeparator);
            insetInputValue.monthLeft.dateInput = leftDateInput;
            insetInputValue.monthLeft.timeInput = leftTimeInput;
            insetInputValue.monthRight.dateInput = rightDateInput;
            insetInputValue.monthRight.timeInput = rightTimeInput;
            break;
    }
    return insetInputValue;
}

/**
 *
 * @param {string} month
 */
import {
    startOfMonth,
    lastDayOfMonth,
    getDaysInMonth,
    // getDay,
    // parseISO,
    format
} from 'date-fns';

function formatFullDate(year: number | string = '', month: number | string = '', day: number | string = ''): string {
    let dateStr = '';
    const monthFull = typeof month === 'number' && month < 10 ? `0${ month}` : month.toString();
    const dayNumberFull = typeof day === 'number' && day < 10 ? `0${ day}` : day.toString();
    dateStr = `${String(year) }-${ monthFull }-${ dayNumberFull}`;
    return dateStr;
}

/**
 * [getWeeks description]
 */
export type WeekStartNumber = 0 | 1 | 2 | 3 | 4 | 5 | 6;
function getWeeks(date: Date, weekStartsOn: WeekStartNumber = 0) {
    const weekDayNotInMonth = {
        dayNumber: '',
        dateNumberFull: '',
        fullDate: '',
    }; // For the first or last week epmtyDays
    const daysInMonth = getDaysInMonth(date); // Get the total number of days in the month
    const year = format(date, 'yyyy');
    const month = format(date, 'MM');
    const lastday = lastDayOfMonth(date); // Get the last day of the month
    const firstDay = startOfMonth(date); // Get the first day of the month
    // Const firstDayInWeek = getDay (firstDay);//The first day belongs to the day of the week
    // What is the first day of the month in the first row?
    const firstDayInWeek = Number(format(firstDay, 'e', { weekStartsOn }));

    const weeks = [];
    let week = [];
    // add empty days to set first day in correct position
    for (let s = 1; s < firstDayInWeek; s++) {
        week.push(weekDayNotInMonth);
    }

    for (let d = 0; d < daysInMonth; d++) {
        const dayNumber = d + 1;
        const dayNumberFull = dayNumber < 10 ? `0${ dayNumber}` : dayNumber.toString();
        const fullDate = formatFullDate(year, month, dayNumber);

        week.push({
            dayNumber,
            dayNumberFull,
            fullDate,
        });

        if (week.length === 7) {
            weeks.push(week);
            week = [];
        } else if (fullDate === format(lastday, 'yyyy-MM-dd')) {
            // Last week alone
            weeks.push(week);
            week = [];
        }
    }
    return weeks;
}

const getMonthTable = (month: Date, weekStartsOn: WeekStartNumber) => {
    const weeks = getWeeks(month, weekStartsOn);
    const monthText = format(month, 'yyyy-MM');
    return { monthText, weeks, month };
};

export default getMonthTable;

export { formatFullDate };

export default function getYearAndMonth(year: { left: number; right: number }, month: { left: number; right: number }) {
    const nowYear = new Date().getFullYear();
    const nowMonth = new Date().getMonth();

    const rightMonth = month.right || (nowMonth + 2);
    const rightYear = year.right || (rightMonth <= 12 ? nowYear : nowYear + 1);

    return {
        year: { left: year.left || nowYear, right: rightYear },
        month: { left: month.left || nowMonth + 1, right: rightMonth <= 12 ? rightMonth : 1 },
    };
}

const getYears = (startYear?: number, endYear?: number) => {
    const currentYear = new Date().getFullYear();
    let start = typeof startYear === 'number' ? startYear : currentYear - 100;
    let end = typeof endYear === 'number' ? endYear : currentYear + 100;
    if (end < start) {
        [start, end] = [end, start];
    }
    return Array.from({ length: end - start + 1 }, (v, i) => start + i);
};
export default getYears;

