import { isAfter as dateFnsIsAfter, parseISO } from 'date-fns';
import isString from '../../utils/isString';

export default function isAfter(date: string | Date, dateToCompare: string | Date) {
    const dayOne = isString(date) ? parseISO(date) : date;
    const dayTwo = isString(dateToCompare) ? parseISO(dateToCompare) : dateToCompare;
    return dateFnsIsAfter(dayOne, dayTwo);
}

import { isBefore as dateFnsIsBefore, parseISO } from 'date-fns';
import isString from '../../utils/isString';

export default function isBefore(date: Date | string, dateToCompare: Date | string) {
    const dayOne = isString(date) ? parseISO(date) : date;
    const dayTwo = isString(dateToCompare) ? parseISO(dateToCompare) : dateToCompare;
    return dateFnsIsBefore(dayOne, dayTwo);
}

import { isWithinInterval, parseISO, isEqual, isBefore } from 'date-fns';
import isString from '../../utils/isString';

/**
 * is the date between start and end?(not including start and end)
 *   - if start > end, return false
 * @param {String|Date} day
 * @param {Object} { start: string|Date, end: string|Date}
 * @returns {Boolean}
 */
export default function isBetween(day: string | Date, { start, end }: { start: string | Date; end: string | Date }) {
    const d = isString(day) ? parseISO(day) : day;
    const s = isString(start) ? parseISO(start) : start;
    const e = isString(end) ? parseISO(end) : end;
    return isBefore(s, e) && isWithinInterval(d, { start: s, end: e }) && !isEqual(d, s) && !isEqual(d, e);
}

export default function isDate(date: any) {
    return Object.prototype.toString.call(date) === '[object Date]';
}

import { isSameDay as dateFnsIsSameDay, parseISO } from 'date-fns';
import isString from '../../utils/isString';

export default function isSameDay(date: string | Date, dateToCompare: string | Date) {
    const dayOne = isString(date) ? parseISO(date) : date;
    const dayTwo = isString(dateToCompare) ? parseISO(dateToCompare) : dateToCompare;
    return dateFnsIsSameDay(dayOne, dayTwo);
}

import isValidDate from './isValidDate';
import isNumber from '../../utils/isNumber';

export default function isTimestamp(ts: any) {
    return isNumber(ts) && isValidDate(new Date(ts));
}

import isNumber from '../../utils/isNumber';
import isValidDate from './isValidDate';

export default function isUnixTimestamp(ts: any) {
    return isNumber(ts) && ts.toString().length === 10 && isValidDate(new Date(ts * 1000));
}

export default function isValidDate(date: any) {
    return date && Object.prototype.toString.call(date) === '[object Date]' && !isNaN(date as any);
}

export default function isValidTimeZone(timeZone?: string | number) {
    return ['string', 'number'].includes(typeof timeZone) && timeZone !== '';
}

import { isWithinInterval as dateFnsIsWithinInterval, parseISO } from 'date-fns';
import isString from '../../utils/isString';

export default function isWithinInterval(day: string | Date, { start, end }: { start: string | Date; end: string | Date }) {
    const d = isString(day) ? parseISO(day) : day;
    const s = isString(start) ? parseISO(start) : start;
    const e = isString(end) ? parseISO(end) : end;
    return dateFnsIsWithinInterval(d, { start: s, end: e });
}

/**
 * @file
 * Various date-related analysis methods
 */
import { isValid, parseISO, parse, Locale } from 'date-fns';

/**
 * Parsing value to Date object
 */
export function compatibleParse(
    value: string,
    formatToken?: string,
    baseDate?: Date,
    locale?: Locale
): Date | null {
    let result = null;
    if (value) {
        if (formatToken) {
            baseDate = baseDate || new Date();
            result = parse(value, formatToken, baseDate, { locale });
        }
        if (!isValid(result)) {
            result = parseISO(value);
        }
        if (!isValid(result)) {
            result = new Date(Date.parse(value));
        }
        const yearInvalid = isValid(result) && String(result.getFullYear()).length > 4;
        if (!isValid(result) || yearInvalid) {
            result = null;
        }
    }
    return result;
}


/**
 * whether value can be parsed with date-fns `parse`
 * 
 * @example
 * isValueParseValid({ value: '2021-01-01', formatToken: 'yyyy-MM-dd' }); // true
 * isValueParseValid({ value: '2021-01-0', formatToken: 'yyyy-MM-dd' }); // false
 * isValueParseValid({ value: '2021-01', formatToken: 'yyyy-MM-dd' }); // false
 */
export function isValueParseValid(options: {
    value: string;
    formatToken: string;
    baseDate?: Date;
    locale?: Locale
}) {
    const { value, locale, formatToken } = options;
    const baseDate = options.baseDate || new Date();
    const result = parse(value, formatToken, baseDate, { locale });
    return isValid(result);
}

